```python
from math import floor, ceil

def calculate_destination_time(n, g, r, li, depart_times):
    def find_next_light(t, i):
        left, right = i, i + n + 1
        result = 0
        while left <= right:
            mid = left + (right - left) // 2
            if i + 1 <= mid <= i + n + 1:
                if t <= li[mid] or (t > li[mid] and mid + 1 <= n <= right):
                    result = mid
                    right = mid - 1
                else:
                    left = mid + 1
            elif mid == i + 1:
                low_index = mid
                high_index = mid
                while low_index < right and high_index < right and high_index - low_index != 1:
                    low_mid = (low_index + high_index) // 2
                    if t <= li[low_mid]: 
                        high_index = low_mid
                    else:
                        low_index = low_mid
                if low_index == low_mid: 
                    result = low_middle
                else: 
                    result = high_index
                break

        return result

    def find_penultimate_light(t, i):
        left, right = i, i + n + 1
        result = 0
        while left <= right:
            mid = left + (right - left) // 2
            if i <= mid <= i + n:
                if t <= li[mid] or (t > li[mid] and mid + 1 <= i or i <= mid <= i + n + 1 <= right):
                    result = mid
                    right = mid - 1
                else:
                    left = mid + 1
            elif mid == i:
                low_index = mid
                high_index = mid
                while low_index < right and high_index < right and high_index - low_index != 1:
                    low_mid = (low_index + high_index) // 2
                    if t <= li[low_mid]: 
                        high_index = low_mid
                    else:
                        low_index = low_mid
                if low_index == low_mid: 
                    result = low_middle
                else: 
                    result = high_index
                break

        return result

    next_highlights = [find_next_light(t, i) for i in range(n+1)]
    penultimate_highlights = [find_penultimate_light(t, i) for i in range(n+1)]

    results = []
    for t in depart_times:
        time_to_next_light = next_highlights.index(t)
        if penultimate_highlights.index(next_highlights[time_to_next_light]) - time_to_next_light != 1:
            next_highlights.append(next_highlights[time_to_next_light])
            penultimate_highlights.append(penultimate_highlights[time_to_next_light])
        results.append(next_highlights[time_to_next_light] + (time_to_next_light - t) // (g + r) * (g + r))
        # Check and adjust the result if the previous timer is already activated
        if penultimate_highlights.index(next_highlights[time_to_next_light]) - time_to_next_light == 1:
            results.append(max(next_highlights[time_to_next_light], results[penultimate_highlights.index(next_highlights[time_to_next_light])] + (next_highlights[time_to_next_light] - results[penultimate_highlights.index(next_highlights[time_to_next_light])]) // (g + r) * (g + r)))
        else:
            results.append(next_highlights[time_to_next_light])

    return results

# Example calls
