def distance_graph(n):
    dp = [0] * (n+1)
    graph = {}

    for i in range(1, n+1):
        for j in range(i+1, n+1):
            if i == j:
                continue
            if i + j <= n:
                gcd_val = gcd(i, j)
                u = (gcd_val // gcd) * (i + j)
                dp[i+1] += (u - 1) * j + dp[1 + gcd_val]
                graph[j + 1] = u
            else:
                u = (i + j) // 2
                dp[i+1] += (u - 1) * j + dp[1 + gcd_val]
                dp[i+1] += (n - i) * (i - 1 + gcd_val + (gcd_val * (gcd_val - 1) // 2) * 1 // i)
                graph[i + j + 1] = u
                graph[1 + gcd_val] = max(u, i)

    return dp[1], graph

