def get_mode_and_count(arr, start, end):
    counter = {i: arr[i] for i in range(start-1, end)}
    counter = {k: v for k, v in counter.items() if v != 0}
    if len(counter) == 0:
        return None, 0
    max_val = max(counter.values())
    if len(counter) == 1:
        return counter, max_val
    modes = []
    for key in counter:
        if counter[key] == max_val:
            modes.append(key)
    return modes, modes[0] if len(modes) == 1 else min(modes)

def find_mode(arr):
    chunk_size = 5000
    max_heap = []
    counter = {i: arr[i] for i in range(len(arr))}
    for i in range(len(arr)):
        while max_heap and arr[i] <= -max_heap[0]:
            heapq.heappush(max_heap, -heapq.heappop(max_heap) * 2)
        if i % chunk_size == 0:
            heapq.heappush(max_heap, -arr[i])
        heapq.heappush(max_heap, -arr[i] * 2)
        count = len(max_heap)
        if count >= 2 and counter[max_heap[0]] == arr[i] + count - 1:
            if counter[max_heap[0]] == counter[max_heap[1]]:
                heapq.heappop(max_heap)
            else:
                counter[max_heap[0]] = arr[i]
                heapq.heappop(max_heap)
        if max_heap and -max_heap[0] * 2 <= counter[-max_heap[0]]:
            counter[max_heap[0]] = -max_heap[0]
            heapq.heappop(max_heap)
            if counter[-max_heap[0]] > -max_heap[0]:
                heapq.heappush(max_heap, -max_heap[0] * 2)
    return max_heap

