def sum_of_madnesses(n, m, p):
    if m == 1:  # One participant
        return 0

    dp = [[0] * (m + 1) for _ in range(m + 1)]
    mdp = [[0] * (m + 1) for _ in range(m + 1)]

    for length in range(1, m + 1):
        for pos in range(length, m + 1):
            for i in range(m + 1):
                pos_i = pos - pow(2, length)
                for j in range(length - 1):
                    dp[pos][i] += dp[pos_i][pow(2, i - j)]
                if pos_i: 
                    for k, v in enumerate(dp[pos]):
                        if j == 0 or k < j: 
                            mdp[pos][-k - 1] += v
                dp[pos][(pos - pos // i) % length] += 1

    return sum(dp[-1]) % p

