def find_all_criminals(n, edges, s, criminals):
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    def dijkstra(start, criminals):
        distances = {node: float('infinity') for node in range(1, n+1)}
        distances[start] = 0
        pq = [(0, start)]
        while pq:
            current_distance, current_node = heappop(pq)
            if current_node in criminals:
                criminals.remove(current_node)
                if not criminals:
                    return current_distance
            for neighbor, weight in graph[current_node]:
                distance = current_distance + weight
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heappush(pq, (distance, neighbor))
        return float('infinity')

    return dijkstra(s, set(criminals))

